def day_stats(hours, readings):
    low = high = readings[0]
    total = night_total = 0
    night_count = 0
    for i in range(len(readings)):
        value = readings[i]
        total += value
        if value < low:
            low = value
        if value > high:
            high = value
        if hours[i] >= 19 or hours[i] < 7:
            night_total += value
            night_count += 1
    return high, low, total / len(readings), night_total / night_count

practice_questions.code:
def day_stats(hours, readings):
    low = high = readings[0]
    total = night_total = 0
    night_count = 0
    for i in range(len(readings)):
        value = readings[i]
        total += value
        if value < low:
            low = value
        if value > high:
            high = value
        if hours[i] >= 19 or hours[i] < 7:
            night_total += value
            night_count += 1
    return high, low, total / len(readings), night_total / night_count
